interface.definition:
a!localVariables(
  local!data: #"SYSTEM_SYSRULES_fromJson_v1"(ri!json).listOfQuestions,
  local!columns: touniformstring(property(index(local!data, 1, {}), "question", {})),
  local!columnsGrid: {"Document Name", local!columns},
  {
    #"SYSTEM_SYSRULES_gridField_v2"(
      label: "Read-only Grid - For Dynamic JSON",
      labelPosition: "ABOVE",
      data: todatasubset(
        #"SYSTEM_SYSRULES_forEach"(
          items: local!data,
          expression: {
            id: fv!index,
            question: touniformstring(fv!item.question),
            answer: touniformstring(fv!item.answer)
          }
        ),
        fv!pagingInfo
      ),
      pagingSaveInto: fv!pagingInfo,
      columns: {
        #"SYSTEM_SYSRULES_forEach"(
          items: local!columnsGrid,
          expression: 
          a!localVariables(
            local!index: fv!index - 1,
            #"SYSTEM_SYSRULES_gridColumn"(
              label: fv!item,
              /*sortField: fv!item,*/
              value: if(contains(local!columns, fv!item), fv!row.answer[local!index], "Some Doc Name" & fv!row.id)
            )
          )
        )
      },
      pageSize: 10
    )
  }
)

